// 1. 避免重复执行（使用调度队列）
const queue = new Set();
function queueEffect(effect) {
  if (!queue.has(effect)) {
    queue.add(effect);
    Promise.resolve().then(() => {
      queue.forEach(e => e());
      queue.clear();
    });
  }
}

// 2. 支持 computed 计算属性
function computed(getter) {
  let value;
  let dirty = true;

  const runner = effect(() => {
    value = getter();
    dirty = false;
  }, { lazy: true });

  return {
    get value() {
      if (dirty) {
        runner();
      }
      track(this, 'value');
      return value;
    }
  };
}

// 3. 支持 ref 基本类型
function ref(value) {
  return reactive({ value });
}
```

