#### 二、数据传输安全

| 安全措施 | 实现方式 | 作用 |
|----------|----------|------|
| **使用 WSS 协议** | `wss://` 而非 `ws://` | 基于 TLS 加密，防止中间人窃听 |
| **消息签名** | 每条消息携带 HMAC 签名 | 防止数据篡改 |
| **消息加密** | 敏感数据使用应用层加密 | 即使 TLS 被突破仍有保护 |

```javascript
// 客户端：消息签名与加密
class SecureWebSocket {
  constructor(url, secretKey) {
    this.ws = new WebSocket(url);
    this.secretKey = secretKey;
  }

  // 生成消息签名
  async sign(message) {
    const encoder = new TextEncoder();
    const keyData = encoder.encode(this.secretKey);
    const msgData = encoder.encode(message);

    const key = await crypto.subtle.importKey(
      'raw', keyData, { name: 'HMAC', hash: 'SHA-256' },
      false, ['sign']
    );

    const signature = await crypto.subtle.sign('HMAC', key, msgData);
    return btoa(String.fromCharCode(...new Uint8Array(signature)));
  }

  // 发送签名消息
  async send(data) {
    const message = JSON.stringify(data);
    const signature = await this.sign(message);
    this.ws.send(JSON.stringify({
      payload: message,
      signature: signature,
      timestamp: Date.now()
    }));
  }
}
```

```javascript
// 服务端：验证消息签名
const crypto = require('crypto');

function verifySignature(message, signature, secretKey) {
  const hmac = crypto.createHmac('sha256', secretKey);
  hmac.update(message);
  const expected = hmac.digest('base64');

  // 使用定时比较防止时序攻击
  return crypto.timingSafeEqual(
    Buffer.from(signature),
    Buffer.from(expected)
  );
}

ws.on('message', (data) => {
  const { payload, signature, timestamp } = JSON.parse(data);

  // 验证时间戳（防止重放攻击，5 分钟有效期）
  if (Date.now() - timestamp > 5 * 60 * 1000) {
    ws.close(4003, 'Message expired');
    return;
  }

  // 验证签名
  if (!verifySignature(payload, signature, userSecretKey)) {
    ws.close(4003, 'Invalid signature');
    return;
  }

  handleMessage(ws, JSON.parse(payload));
});
