#### 三、连接管理与限流

```javascript
// 服务端：连接限流与频率控制
const userConnections = new Map(); // userId -> Set<WebSocket>
const MAX_CONNECTIONS_PER_USER = 3;
const MESSAGE_RATE_LIMIT = 100; // 每分钟最多 100 条消息

wss.on('connection', (ws, request) => {
  const userId = authenticate(request); // 鉴权后获取 userId

  // 限制单用户最大连接数
  if (!userConnections.has(userId)) {
    userConnections.set(userId, new Set());
  }

  if (userConnections.get(userId).size >= MAX_CONNECTIONS_PER_USER) {
    ws.close(4004, 'Too many connections');
    return;
  }

  userConnections.get(userId).add(ws);

  // 消息频率限制
  ws.messageCount = 0;
  ws.messageTimer = setInterval(() => {
    ws.messageCount = 0;
  }, 60000);

  ws.on('message', () => {
    ws.messageCount++;
    if (ws.messageCount > MESSAGE_RATE_LIMIT) {
      ws.close(4005, 'Rate limit exceeded');
    }
  });

  ws.on('close', () => {
    userConnections.get(userId).delete(ws);
    clearInterval(ws.messageTimer);

    if (userConnections.get(userId).size === 0) {
      userConnections.delete(userId);
    }
  });
});
