#### 四、心跳与断线重连方案

```javascript
// 客户端：完整的心跳与重连实现
class ResilientWebSocket {
  constructor(url, options = {}) {
    this.url = url;
    this.heartbeatInterval = options.heartbeatInterval || 30000; // 30 秒
    this.reconnectDelay = options.reconnectDelay || 5000;       // 5 秒
    this.maxReconnectAttempts = options.maxReconnectAttempts || 5;

    this.ws = null;
    this.heartbeatTimer = null;
    this.heartbeatTimeout = null;
    this.reconnectAttempts = 0;
    this.isManualClose = false;

    this.connect();
  }

  connect() {
    this.ws = new WebSocket(this.url);

    this.ws.onopen = () => {
      console.log('连接建立');
      this.reconnectAttempts = 0;
      this.startHeartbeat();
    };

    this.ws.onmessage = (event) => {
      // 收到服务器心跳响应，重置超时
      if (event.data === 'pong') {
        this.resetHeartbeatTimeout();
      } else {
        this.onMessage?.(event.data);
      }
    };

    this.ws.onclose = (event) => {
      console.log(`连接关闭，代码：${event.code}`);
      this.stopHeartbeat();

      // 非手动关闭时尝试重连
      if (!this.isManualClose) {
        this.attemptReconnect();
      }
    };

    this.ws.onerror = (error) => {
      console.error('连接错误', error);
      this.onError?.(error);
    };
  }

  startHeartbeat() {
    // 定期发送心跳
    this.heartbeatTimer = setInterval(() => {
      if (this.ws && this.ws.readyState === WebSocket.OPEN) {
        this.ws.send('ping');

        // 设置心跳超时，如果服务器未及时响应则断开
        this.heartbeatTimeout = setTimeout(() => {
          console.warn('心跳超时，断开连接');
          this.ws.close();
        }, this.heartbeatInterval);
      }
    }, this.heartbeatInterval);
  }

  resetHeartbeatTimeout() {
    if (this.heartbeatTimeout) {
      clearTimeout(this.heartbeatTimeout);
      this.heartbeatTimeout = null;
    }
  }

  stopHeartbeat() {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
    this.resetHeartbeatTimeout();
  }

  attemptReconnect() {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('达到最大重连次数');
      this.onMaxReconnectExceeded?.();
      return;
    }

    this.reconnectAttempts++;
    const delay = this.reconnectDelay * Math.pow(2, this.reconnectAttempts - 1); // 指数退避

    console.log(`${delay}ms 后尝试重连 (${this.reconnectAttempts}/${this.maxReconnectAttempts})`);

    setTimeout(() => this.connect(), delay);
  }

  send(data) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(data);
    } else {
      throw new Error('WebSocket 未连接');
    }
  }

  close() {
    this.isManualClose = true;
    this.stopHeartbeat();
    if (this.ws) {
      this.ws.close();
    }
  }
}
```

